"""Generate the named-colour tables and colour sequences of plt::colors.

Run with the reference venv:  .venv/bin/python -I crates/plt/tools/gen_color_tables.py
Writes crates/plt/src/colors/named_data.rs and sequence_data.rs (committed).
"""

import pathlib

import matplotlib
import matplotlib.colors as mcolors
from matplotlib import _color_data

OUT = pathlib.Path(__file__).resolve().parents[1] / "src" / "colors"
HEADER = """//! {what}
//!
//! Generated by `crates/plt/tools/gen_color_tables.py` from matplotlib's
//! `_color_data.py` and colour-sequence registry. Do not edit by hand.
"""


def hex_table(name, doc, table):
    rows = [f"/// {doc}", f"pub(super) const {name}: &[(&str, &str)] = &["]
    rows += [f'    ("{k}", "{v.lower()}"),' for k, v in table.items()]
    rows.append("];")
    return "\n".join(rows)


def named():
    base = ["/// The single-letter base colours (`b`, `g`, `r`, ...).",
            "pub(super) const BASE: &[(&str, [f64; 3]); 8] = &["]
    for k, (r, g, b) in _color_data.BASE_COLORS.items():
        base.append(f'    ("{k}", [{float(r)!r}, {float(g)!r}, {float(b)!r}]),')
    base.append("];")
    parts = [
        HEADER.format(what="Named colour tables (base, Tableau, CSS4, xkcd)."),
        "\n".join(base),
        hex_table("TABLEAU", "Tableau palette (`tab:blue`, ...).", _color_data.TABLEAU_COLORS),
        hex_table("CSS4", "The 148 CSS4 colour names.", _color_data.CSS4_COLORS),
        hex_table("XKCD", "The xkcd colour survey names (`xkcd:sky blue`, ...).", _color_data.XKCD_COLORS),
    ]
    (OUT / "named_data.rs").write_text("\n\n".join(parts) + "\n")


def sequences():
    rows = [HEADER.format(what="Built-in colour sequences (`tab10`, `Set1`, ...)."),
            '#![allow(clippy::unreadable_literal, reason = "exact floats copied from matplotlib")]',
            "",
            "/// `(name, colours)` in matplotlib's registry order.",
            "pub(super) const SEQUENCES: &[(&str, &[[f64; 3]])] = &["]
    for name in matplotlib.color_sequences:
        colors = [mcolors.to_rgb(c) for c in matplotlib.color_sequences[name]]
        rows.append(f'    ("{name}", &[')
        for r, g, b in colors:
            rows.append(f"        [{r!r}, {g!r}, {b!r}],")
        rows.append("    ]),")
    rows.append("];")
    (OUT / "sequence_data.rs").write_text("\n".join(rows) + "\n")


if __name__ == "__main__":
    named()
    sequences()
    print("wrote", OUT / "named_data.rs", OUT / "sequence_data.rs")
